window.AUTH=window.AUTH||{};window.AUTH["16-1215"]={"d":"16-1215","id":"2017/16-1215","n":"Lamar, Archer & Cofrin, LLP v. Appling","briefs":[{"k":"petitioner","label":"Brief of petitioner Lamar, Archer & Cofrin, LLP","date":"2018-02-26","url":"https://www.supremecourt.gov/DocketPDF/16/16-1215/36700/20180226174851639_2018-02-26%20Lamar%20Opening%20Br%20with%20addendum.pdf","side":"pet","n":43},{"k":"respondent","label":"Brief of respondent R. Scott Appling","date":"2018-03-28","url":"https://www.supremecourt.gov/DocketPDF/16/16-1215/40471/20180328190144228_16-1215.bs.pdf","side":"res","n":56},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2018-04-04","url":"https://www.supremecourt.gov/DocketPDF/16/16-1215/42400/20180404200306861_16-1215bsUnitedStates.pdf","side":"us","n":61},{"k":"reply","label":"Reply of petitioner Lamar, Archer & Cofrin, LLP","date":"2018-04-10","url":"https://www.supremecourt.gov/DocketPDF/16/16-1215/42908/20180410131914412_2018-04-10%20Lamar%20Reply.pdf","side":"pet","n":29}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Albinak v. Kuhn (In re Manufacturers Trading Corp.)","cite":"149 F.2d 108","y":1945,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/149/108/","by":{"0":"44","1":"42","2":"24"},"q":[{"src":"brief","b":2,"text":"[n]o cases have been cited to us, and none has been found by careful examination, which confines a statement respecting one’s financial condition as limited to a detailed statement of assets and liabilities.","cite":"149 F.2d 108, 110"}]},{"t":"case","label":"Barnes v. Belice (In re Belice)","cite":"461 B.R. 564","y":2011,"court":"B.A.P. 9th Cir.","url":"https://www.courtlistener.com/c/B.R./461/564/","by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"it is difficult to conceive of any false representation regarding an asset or a particular financial condition that could justifiably induce ‘an extension, renewal or refinancing of credit’ that would not also be a ‘statement respecting the debtor’s . . . financial condition’ under the broad interpretation.","cite":"461 B.R. 564, 577 n.8"}]},{"t":"case","label":"Beneficial Finance Co. v. Lathrop","cite":"207 So. 2d 220","y":1968,"court":"La. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/207/220/","by":{"0":"44"}},{"t":"case","label":"Beneficial Finance Co. v. Machie","cite":"263 A.2d 707","y":1969,"court":"Conn. Cir. Ct.","url":"https://www.courtlistener.com/c/A.2d/263/707/","by":{"0":"44"}},{"t":"case","label":"Brown v. Felsen","cite":"442 U.S. 127","y":1979,"id":"1978/78-58","sc":1,"by":{"0":"7"}},{"t":"case","label":"California Divison of Labor Standards Enforcement v. Dillingham Construction, N.A., Inc.","cite":"519 U.S. 316","y":1997,"id":"1996/95-789","sc":1,"by":{"0":"18, 31, 32, 33"},"q":[{"src":"brief","b":0,"text":"everything is related to everything else,","cite":"519 U.S. 316, 335"},{"src":"brief","b":0,"text":"everything is related to everything else.","cite":"519 U.S. 316, 335"}]},{"t":"case","label":"Clancy v. First National Bank","cite":"408 F.2d 899","y":1969,"url":"https://www.courtlistener.com/c/F.2d/408/899/","by":{"0":"45"}},{"t":"case","label":"Cohen v. de la Cruz","cite":"523 U.S. 213","y":1998,"id":"1997/96-1923","sc":1,"by":{"0":"5, 7, 19, 34, 38","2":"2, 29","3":"16"},"q":[{"src":"brief","b":0,"text":"basic policy . . . of affording relief only to an ‘honest but unfortunate debtor.’","cite":"523 U.S. 213, 217"},{"src":"argument","who":"Mr. Hughes","text":"Prior to that, the Court looked at Cohen v. de la Cruz, which was a case about a fraudulent scheme to overcharge rents, in violation of state law."}]},{"t":"case","label":"Cooper Industies, Inc. v. Aviall Servics, Inc.","cite":"543 U.S. 157","y":2004,"id":"2004/02-1192","sc":1,"by":{"0":"25, 26"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"by":{"0":"27"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"by":{"0":"26"}},{"t":"case","label":"Field v. Mans","cite":"516 U.S. 59","y":1995,"id":"1995/94-967","sc":1,"by":{"0":"passim","1":"passim","2":"3, 14, 16, 21, 29, 30","3":"11, 17, 19"},"q":[{"src":"brief","b":1,"text":"practices of consumer finance companies, which sometimes have encouraged * * * falsity by their borrowers for the very purpose of insulating their own claims from discharge.","cite":"516 U.S. at 76"},{"src":"brief","b":2,"text":"the peculiar potential of financial statements to be misused not just by debtors, but by creditors who know their bankruptcy law.","cite":"516 U.S. at 76"},{"src":"argument","who":"Mr. Garre","text":"This Court recognized that in Field versus Mans, which makes it a little bit different than the typical legislative history case. The government strenuously argued that the Court should interpret 523(a)(2)(A) in Field in light of that specific problem it was seeking to address."}]},{"t":"case","label":"Fogerty v. Fantasy, Inc.","cite":"510 U.S. 517","y":1994,"id":"1993/92-1750","sc":1,"by":{"0":"36"}},{"t":"case","label":"Gardner v. American Century Mortgage Investors (In re Gardner)","cite":"577 F.2d 928","y":1978,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/577/928/","by":{"0":"43"}},{"t":"case","label":"Gomez-Perez v. Potter","cite":"553 U.S. 474","y":2008,"id":"2007/06-1321","sc":1,"by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"‘[n]egative implications raised by disparate provisions are strongest’ in those instances in which the relevant statutory provisions were ‘considered simultaneously when the language raising the implication was inserted,’","cite":"553 U.S. 474, 486"}]},{"t":"case","label":"Grogan v. Garner","cite":"498 U.S. 279","y":1991,"id":"1990/89-1149","sc":1,"by":{"0":"passim","1":"38, 54","2":"2, 19","3":"15, 16"},"q":[{"src":"brief","b":0,"text":"unlikely that Congress . . . would have favored the interest in giving perpetrators of fraud a fresh start over the interest in protecting victims of fraud.","cite":"498 U.S. 279, 287"},{"src":"brief","b":0,"text":"[t]he policy against discharging debts incurred by fraud is deeply embedded in the bankruptcy law, and has been recognized in every bankruptcy statute since the Act of March 2, 1867.","cite":"498 U.S. 279"},{"src":"brief","b":2,"text":"creditors’ interest in recovering full payment of debts * * * outweigh[s] the debtors’ interest in a complete fresh start.","cite":"498 U.S. at 287"},{"src":"argument","who":"Mr. Hughes","text":"Prior to that, in Grogan, with securities fraud, that was a (2)(A) case. All of these cases that deal with fraud entirely outside the lending capacity come up as (2)(A) cases."}]},{"t":"case","label":"J.W. Ould Co. v. Davis","cite":"246 F. 228","y":1917,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F./246/228/","by":{"0":"8","1":"41","2":"22"}},{"t":"case","label":"Martin v. Franklin Capital Corp.","cite":"546 U.S. 132","y":2005,"id":"2005/04-1140","sc":1,"by":{"0":"36"},"q":[{"src":"brief","b":0,"text":"[S]uch a bold departure from traditional practice would have surely drawn . . . explicit statutory language and legislative comment.","cite":"546 U.S. 132, 137"}]},{"t":"case","label":"Murphy v. Smith, ___ S. Ct. ____","cite":"2018 WL 987346","y":2018,"court":"U.S. Feb. 21","by":{"0":"27, 29"},"q":[{"src":"brief","b":0,"text":"Congress didn’t choose those other words. And respect for Congress’s prerogatives as policymaker means carefully attending to the words it chose rather than replacing them with others of our own.","cite":"2018 WL 987346"}]},{"t":"case","label":"Palter v. Lake Sales, Inc. (In re Palter)","cite":"435 F.2d 120","y":1970,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/435/120/","by":{"0":"43"}},{"t":"case","label":"Personal Finance Co. v. Bruns","cite":"84 A.2d 32","y":1951,"court":"N.J. Super. Ct. App. Div.","url":"https://www.courtlistener.com/c/A.2d/84/32/","by":{"0":"44"}},{"t":"case","label":"Ransom v. FIA Card Services, N.A.","cite":"562 U.S. 61","y":2011,"id":"2010/09-907","sc":1,"by":{"0":"22","2":"10"},"q":[{"src":"brief","b":0,"text":"[I]nterpretation of the Bankruptcy Code starts ‘where all such inquiries must begin: with the language of the statute itself.’","cite":"562 U.S. 61, 69"},{"src":"brief","b":2,"text":"‘with the language of the statute itself.’","cite":"562 U.S. 61, 69"}]},{"t":"case","label":"Regents of the University of California v. Public Employment Relations Board","cite":"485 U.S. 589","y":1988,"id":"1987/86-935","sc":1,"by":{"0":"33"}},{"t":"case","label":"Rogers v. Gardner","cite":"226 F.2d 864","y":1955,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/226/864/","by":{"0":"43"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"0":"30","1":"26","3":"9"},"q":[{"src":"brief","b":0,"text":"[w]here Congress includes particular language in one section of a statute but omits it in another section of the same Act, it is generally presumed that Congress acts intentionally and purposely in the disparate inclusion or exclusion.","cite":"464 U.S. 16, 23"}]},{"t":"case","label":"Schweizer v. City Loan Co. (In re Schweizer)","cite":"271 F.2d 95","y":1959,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/271/95/","by":{"0":"43"}},{"t":"case","label":"Tenn v. First Hawaiian Bank","cite":"549 F.2d 1356","y":1977,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/549/1356/","by":{"0":"44","1":"44","2":"24"}},{"t":"case","label":"Travelers Indemnity Co. v. Bailey","cite":"557 U.S. 137","y":2009,"id":"2008/08-295","sc":1,"by":{"0":"31","1":"22, 23","3":"12"}},{"t":"case","label":"United States v. Standard Brewery Co.","cite":"251 U.S. 210","y":1920,"id":"scdb/1919-173","sc":1,"by":{"0":"25, 26"},"q":[{"src":"brief","b":0,"text":"all of the words used in a legislative act are to be given force and meaning,","cite":"251 U.S. at 218"}]},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"by":{"0":"35"},"q":[{"src":"brief","b":0,"text":"[i]t is not lightly to be assumed that Congress intended to depart from [such a] long established policy.","cite":"503 U.S. 329, 336"}]},{"t":"case","label":"Utility Air Regulatory Group v. EPA","cite":"134 S. Ct. 2427","y":2014,"id":"2013/12-1146","sc":1,"by":{"0":"26","2":"12"},"q":[{"src":"brief","b":0,"text":"the words of a statute must be read in their context,","cite":"134 S. Ct. 2427, 2441"}]},{"t":"case","label":"Whitman v. American Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"by":{"0":"36"}},{"t":"case","label":"Yates v. Boteler","cite":"163 F.2d 953","y":1947,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/163/953/","by":{"0":"43"}},{"t":"usc","label":"11 U.S.C. § 32","url":"https://www.law.cornell.edu/uscode/text/11/32","subs":["(b)(3)(1926)"],"by":{"0":"45"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(31)(A)","(32)(A)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"23","1":"25","2":"2, 12","3":"6"},"q":[{"src":"brief","b":0,"text":"corporation of which the debtor is a director, officer, or person in control.","cite":"11 U.S.C. § 101(31)(A)"},{"src":"brief","b":1,"text":"financial condition such that the sum of such entity’s debts is greater than all of such entity’s property.","cite":"11 U.S.C. § 101(32)(A)"}]},{"t":"usc","label":"11 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/11/523","subs":["(a)(2)","(a)(2)(A)","(a)(2)(B)(ii)","(a)(2)(B)(iii)","(a)(2)(B)(iv)","(a)","(a)(1)","(a)(2)(B)","(a)(2)(B)(i)","(d)"],"stext":{"head":"§523. Exceptions to discharge","paras":[[0,"(a) A discharge under section 727, 1141, 1192 1 1228(a), 1228(b), or 1328(b) of this title does not discharge an individual debtor from any debt—"],[1,"(1) for a tax or a customs duty—"],[2,"(A) of the kind and for the periods specified in section 507(a)(3) or 507(a)(8) of this title, whether or not a claim for such tax was filed or allowed;"],[2,"(B) with respect to which a return, or equivalent report or notice, if required—"],[3,"(i) was not filed or given; or"],[3,"(ii) was filed or given after the date on which such return, report, or notice was last due, under applicable law or under any extension, and after two years before the date of the filing of the petition; or"],[2,"(C) with respect to which the debtor made a fraudulent return or willfully attempted in any manner to evade or defeat such tax;"],[1,"(2) for money, property, services, or an extension, renewal, or refinancing of credit, to the extent obtained by—"],[2,"(A) false pretenses, a false representation, or actual fraud, other than a statement respecting the debtor's or an insider's financial condition;"],[2,"(B) use of a statement in writing—"],[3,"(i) that is materially false;"],[3,"(ii) respecting the debtor's or an insider's financial condition;"],[3,"(iii) on which the creditor to whom the debtor is liable for such money, property, services, or credit reasonably relied; and"],[3,"(iv) that the debtor caused to be made or published with intent to deceive; or"],[2,"(C)(i) for purposes of subparagraph (A)—"],[3,"(I) consumer debts owed to a single creditor and aggregating more than $500 2 for luxury goods or services incurred by an individual debtor on or within 90 days before the order for relief under this title are presumed to be nondischargeable; and"],[3,"(II) cash advances aggregating more than $750 2 that are extensions of consumer credit under an open end credit plan obtained by an individual debtor on or within 70 days before the order for relief under this title, are presumed to be nondischargeable; and"],[2,"(ii) for purposes of this subparagraph—"],[3,"(I) the terms \"consumer\", \"credit\", and \"open end credit plan\" have the same meanings as in section 103 of the Truth in Lending Act; and"],[3,"(II) the term \"luxury goods or services\" does not include goods or services reasonably necessary for the support or maintenance of the debtor or a dependent of the debtor;"],[1,"(3) neither listed nor scheduled under section 521(a)(1) of this title, with the name, if known to the debtor, of the creditor to whom such debt is owed, in time to permit—"],[2,"(A) if such debt is not of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim, unless such creditor had notice or actual knowledge of the case in time for such timely filing; or"],[2,"(B) if such debt is of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim and timely request for a determination of dischargeability of such debt under one of such paragraphs, unless such creditor had notice or actual knowledge of the case in time for such timely filing and request;"],[1,"(4) for fraud or defalcation while acting in a fiduciary capacity, embezzlement, or larceny;"],[1,"(5) for a domestic support obligation;"],[1,"(6) for willful and malicious injury by the debtor to another entity or to the property of another entity;"],[1,"(7) to the extent such debt is for a fine, penalty, or forfeiture payable to and for the benefit of a governmental unit, and is not compensation for actual pecuniary loss, other than a tax penalty—"],[2,"(A) relating to a tax of a kind not specified in paragraph (1) of this subsection; or"],[2,"(B) imposed with respect to a transaction or event that occurred before three years before the date of the filing of the petition;"],[1,"(8) unless excepting such debt from discharge under this paragraph would impose an undue hardship on the debtor and the debtor's dependents, for—"],[2,"(A)(i) an educational benefit overpayment or loan made, insured, or guaranteed by a governmental unit, or made under any program funded in whole or in part by a governmental unit or nonprofit institution; or"],[2,"(ii) an obligation to repay funds received as an educational benefit, scholarship, or stipend; or"],[2,"(B) any other educational loan that is a qualified education loan, as defined in section 221(d)(1) of the Internal Revenue Code of 1986, incurred by a debtor who is an individual;"],[1,"(9) for death or personal injury caused by the debtor's operation of a motor vehicle, vessel, or aircraft if such operation was unlawful because the debtor was intoxicated from using alcohol, a drug, or another substance;"],[1,"(10) that was or could have been listed or scheduled by the debtor in a prior case concerning the debtor under this title or under the Bankruptcy Act in which the debtor waived discharge, or was denied a discharge under section 727(a)(2), (3), (4), (5), (6), or (7) of this title, or under section 14c(1), (2), (3), (4), (6), or (7) of such Act;"],[1,"(11) provided in any final judgment, unreviewable order, or consent order or decree entered in any court of the United States or of any State, issued by a Federal depository institutions regulatory agency, or contained in any settlement agreement entered into by the debtor, arising from any act of fraud or defalcation while acting in a fiduciary capacity committed with respect to any depository institution or insured credit union;"],[1,"(12) for malicious or reckless failure to fulfill any commitment by the debtor to a Federal depository institutions regulatory agency to maintain the capital of an insured depository institution, except that this paragraph shall not extend any such commitment which would otherwise be terminated due to any act of such agency;"],[1,"(13) for any payment of an order of restitution issued under title 18, United States Code;"],[1,"(14) incurred to pay a tax to the United States that would be nondischargeable pursuant to paragraph (1);"],[1,"(14A) incurred to pay a tax to a governmental unit, other than the United States, that would be nondischargeable under paragraph (1);"],[1,"(14B) incurred to pay fines or penalties imposed under Federal election law;"],[1,"(15) to a spouse, former spouse, or child of the debtor and not of the kind described in paragraph (5) that is incurred by the debtor in the course of a divorce or separation or in connection with a separation agreement, divorce decree or other order of a court of record, or a determination made in accordance with State or territorial law by a governmental unit;"],[1,"(16) for a fee or assessment that becomes due and payable after the order for relief to a membership association with respect to the debtor's interest in a unit that has condominium ownership, in a share of a cooperative corporation, or a lot in a homeowners association, for as long as the debtor or the trustee has a legal, equitable, or possessory ownership interest in such unit, such corporation, or such lot, but nothing in this paragraph shall except from discharge the debt of a debtor for a membership association fee or assessment for a period arising before entry of the order for relief in a pending or subsequent bankruptcy case;"],[1,"(17) for a fee imposed on a prisoner by any court for the filing of a case, motion, complaint, or appeal, or for other costs and expenses assessed with respect to such filing, regardless of an assertion of poverty by the debtor under subsection (b) or (f)(2) of section 1915 of title 28 (or a similar non-Federal law), or the debtor's status as a prisoner, as defined in section 1915(h) of title 28 (or a similar non-Federal law);"],[1,"(18) owed to a pension, profit-sharing, stock bonus, or other plan established under section 401, 403, 408, 408A, 414, 457, or 501(c) of the Internal Revenue Code of 1986, under—"],[2,"(A) a loan permitted under section 408(b)(1) of the Employee Retirement Income Security Act of 1974, or subject to section 72(p) of the Internal Revenue Code of 1986; or"],[2,"(B) a loan from a thrift savings plan permitted under subchapter III of chapter 84 of title 5, that satisfies the requirements of section 8433(g) of such title;"],[1,"but nothing in this paragraph may be construed to provide that any loan made under a governmental plan under section 414(d), or a contract or account under section 403(b), of the Internal Revenue Code of 1986 constitutes a claim or a debt under this title;"],[1,"(19) that—"],[2,"(A) is for—"],[3,"(i) the violation of any of the Federal securities laws (as that term is defined in section 3(a)(47) of the Securities Exchange Act of 1934), any of the State securities laws, or any regulation or order issued under such Federal or State securities laws; or"],[3,"(ii) common law fraud, deceit, or manipulation in connection with the purchase or sale of any security; and"],[2,"(B) results, before, on, or after the date on which the petition was filed, from—"],[3,"(i) any judgment, order, consent order, or decree entered in any Federal or State judicial or administrative proceeding;"],[3,"(ii) any settlement agreement entered into by the debtor; or"],[3,"(iii) any court or administrative order for any damages, fine, penalty, citation, restitutionary payment, disgorgement payment, attorney fee, cost, or other payment owed by the debtor; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/523?type=usc&year=mostrecent&link-type=html"},"by":{"0":"1, 2, 5, 2, 5, 15, 22, 47, 12, 12, 12","2":"10, 10, 10, 26, 26, 26, 26, 26, 26, 26","3":"1"},"q":[{"src":"brief","b":0,"text":"statements respecting . . . financial condition.","cite":"11 U.S.C. § 523(a)(2)(B)(ii)"},{"src":"brief","b":0,"text":"statement respecting the debtor’s or an insider’s financial condition.","cite":"11 U.S.C. § 523(a)(2)(A)"},{"src":"brief","b":2,"text":"does not discharge an individual debtor from any debt * * * for money, property, services, or an extension, renewal, or refinancing of credit, to the extent obtained by * * * false pretenses, a false representation, or actual fraud, other than a statement respecting the debtor’s or an insider’s financial condition.","cite":"11 U.S.C. 523(a)(2)(A)"},{"src":"brief","b":2,"text":"a statement * * * respecting the debtor’s or an insider’s financial condition.","cite":"11 U.S.C. 523(a)(2)(B)(ii)"},{"src":"argument","who":"Mr. Garre","text":"Yet, Respondent and the government ask this Court to interpret Section 523 and, in particular, Congress's use of \"respecting\" to eliminate the meaning of \"financial condition,\" of a term of art, and essentially to substitute the word \"finances\" for it."},{"src":"argument","who":"Mr. Garre","text":"Their rule would render the baseline rule in Section 523, that debts procured by fraud are not dischargeable, inapplicable to a common fact pattern under Section 523, which is statements made about one's finances to secure credit."}]},{"t":"usc","label":"11 U.S.C. § 1142","url":"https://www.law.cornell.edu/uscode/text/11/1142","subs":["(a)"],"stext":{"head":"§1142. Implementation of plan","paras":[[0,"(a) Notwithstanding any otherwise applicable nonbankruptcy law, rule, or regulation relating to financial condition, the debtor and any entity organized or to be organized for the purpose of carrying out the plan shall carry out the plan and shall comply with any orders of the court."],[0,"(b) The court may direct the debtor and any other necessary party to execute or deliver or to join in the execution or delivery of any instrument required to effect a transfer of property dealt with by a confirmed plan, and to perform any other act, including the satisfaction of any lien, that is necessary for the consummation of the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1142?type=usc&year=mostrecent&link-type=html"},"by":{"0":"29","2":"12","3":"9"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"law","label":"Pub. L. No. 86-621","url":"https://www.govinfo.gov/link/statute/74/408","by":{"0":"445"}},{"t":"case","label":"Bullock v. BankChampaign, N.A.","cite":"569 U.S. 267","y":2013,"id":"2012/11-1518","sc":1,"by":{"1":"38, 39, 54"},"q":[{"src":"brief","b":1,"text":"the uniformity of federal law * * * is fundamental to the proper administration of the bankruptcy system.","cite":"569 U.S. at 276"}]},{"t":"case","label":"Cefalu v. B.F. Goodrich Co.","cite":"871 F.2d 1290","url":"https://www.courtlistener.com/c/F.2d/871/1290/","by":{"1":"52"},"q":[{"src":"brief","b":1,"text":"gives the plan’s participants and administrators a clear understanding of their rights and obligations.","cite":"871 F.2d 1290, 1296"}]},{"t":"case","label":"Coleman v. Nationwide Life Ins. Co.","cite":"969 F.2d 54","y":1992,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/969/54/","by":{"1":"52"},"q":[{"src":"brief","b":1,"text":"costly, litigious disputes over what informal modifications may have been made to [the] written instrument.","cite":"969 F.2d 54, 60"}]},{"t":"case","label":"Coventry Health Care of Mo., Inc. v. Nevils","cite":"137 S. Ct. 1190","y":2017,"id":"2016/16-149","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"to reach any subject that has ‘a connection with, or reference to,’ the topics the statute enumerates.","cite":"137 S. Ct. 1190, 1197"}]},{"t":"case","label":"Dial Fin. Co. v. Duthu","cite":"188 So. 2d 151","y":1966,"court":"La. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/188/151/","by":{"1":"45"},"q":[{"src":"brief","b":1,"text":"[t]he bankruptcy act does not speak of a ‘financial statement’ in the sense of a formal listing and detailing of assets and liabilities.","cite":"188 So. 2d 151, 154"}]},{"t":"case","label":"Engler v. Van Steinburg","cite":"744 F.2d 1060","y":1984,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/744/1060/","by":{"1":"34","2":"14"}},{"t":"case","label":"First Nat’l Bank of Cincinnati v. Flershem","cite":"290 U.S. 504","y":1934,"id":"scdb/1933-046","sc":1,"by":{"1":"58"}},{"t":"case","label":"Fralick v. Hasenberg","cite":"2006 WL 2390289","y":2006,"court":"D. Md.","by":{"1":"34"}},{"t":"case","label":"Husky Int’l Elecs. v. Ritz","cite":"136 S. Ct. 1581","y":2016,"id":"2015/15-145","sc":1,"by":{"1":"38, 40","2":"20"},"q":[{"src":"brief","b":2,"text":"encompasses forms of fraud, like fraudulent conveyance schemes, that can be effected without a false representation.","cite":"136 S. Ct. 1581, 1586"},{"src":"argument","who":"Mr. Hughes","text":"And so just to look at this Court's recent 523(a)(2) cases, two years ago, the Court considered Husky International Electronics about fraudulent conveyance, which was a (2)(A) case."}]},{"t":"case","label":"Johnson v. Dowling","cite":"2013 WL 684681","y":2013,"court":"W.D. Va.","by":{"1":"54"}},{"t":"case","label":"Kawaauhau v. Geiger","cite":"523 U.S. 57","y":1998,"id":"1997/97-115","sc":1,"by":{"1":"38"},"q":[{"src":"brief","b":1,"text":"the ‘well-known’ guide that exceptions to discharge ‘should be confined to those plainly expressed.’","cite":"523 U.S. 57, 62"}]},{"t":"case","label":"Kleppe v. New Mexico","cite":"426 U.S. 529","y":1976,"id":"1975/74-1488","sc":1,"by":{"1":"19","2":"13","3":"5"},"q":[{"src":"brief","b":1,"text":"approved legislation respecting the public lands ‘[i]f it be found to be necessary, for the protection of the public, or of intending settlers on the public lands.’","cite":"426 U.S. 529, 540"}]},{"t":"case","label":"Lee v. Weisman","cite":"505 U.S. 577","y":1992,"id":"1991/90-1014","sc":1,"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"Congress shall make no law establishing Religion.","cite":"505 U.S. 577, 613"}]},{"t":"case","label":"Lemon v. Kurtzman","cite":"403 U.S. 602","y":1971,"id":"1970/89","sc":1,"by":{"1":"18","3":"5"},"q":[{"src":"brief","b":1,"text":"[a] law may be one ‘respecting’ the forbidden objective while falling short of its total realization.","cite":"403 U.S. 602, 612"}]},{"t":"case","label":"Local Loan Co. v. Hunt","cite":"292 U.S. 234","y":1934,"id":"scdb/1933-054","sc":1,"by":{"1":"4"},"q":[{"src":"brief","b":1,"text":"a clear field for future effort, unhampered by the pressure and discouragement of pre-existing debt.","cite":"292 U.S. 234, 244"}]},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"1":"46","2":"26"},"q":[{"src":"brief","b":1,"text":"Congress is presumed to be aware of an administrative or judicial interpretation of a statute and to adopt that interpretation when it re-enacts a statute without change.","cite":"434 U.S. 575, 580"},{"src":"brief","b":2,"text":"Congress adopts a new law incorporating sections of a prior law, Congress normally can be presumed to have had knowledge of the interpretation given to the incorporated law, at least insofar as it affects the new statute.","cite":"434 U.S. 575, 581"}]},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"by":{"1":"22","3":"16"},"q":[{"src":"brief","b":1,"text":"a limiting principle consistent with the structure of the statute and its other provisions.","cite":"570 U.S. 48, 60"},{"src":"argument","who":"Mr. Garre","text":"And this Court relied upon similar considerations, for example, in Maracich versus Spears, where it refused to interpret an exception to the Driver's Privacy Protection Act, in such a broad manner that it would really strike at the heart of the overlying objective there."}]},{"t":"case","label":"Mellouli v. Lynch","cite":"135 S. Ct. 1980","y":2015,"id":"2014/13-1034","sc":1,"by":{"1":"22"}},{"t":"case","label":"Midlantic Nat’l Bank v. New Jersey Dep’t of Envtl. Prot.","cite":"474 U.S. 494","y":1986,"id":"1985/84-801","sc":1,"by":{"1":"46"},"q":[{"src":"brief","b":1,"text":"rule with particular care in construing the scope of bankruptcy codifications.","cite":"474 U.S. 494, 501"}]},{"t":"case","label":"Morales v. Trans World Airlines, Inc.","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"by":{"1":"21, 22, 23"},"q":[{"src":"brief","b":1,"text":"only pre-empts the States from actually prescribing rates, routes, or services.","cite":"504 U.S. at 385"},{"src":"brief","b":1,"text":"[t]here is, of course, a cutoff at some point, where the connection between the insurer’s action complained of and the insurance coverage would be thin to the point of absurd.","cite":"504 U.S. at 388, 390"}]},{"t":"case","label":"Morlang v. Cox","cite":"222 B.R. 83","y":1998,"court":"W.D. Va.","url":"https://www.courtlistener.com/c/B.R./222/83/","by":{"1":"34"}},{"t":"case","label":"Northwest, Inc. v. Ginsberg","cite":"134 S. Ct. 1422","y":2014,"id":"2013/12-462","sc":1,"by":{"1":"21"}},{"t":"case","label":"Pilot Life Ins. Co. v. Dedeaux","cite":"481 U.S. 41","y":1987,"id":"1986/85-1043","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"[t]he phrase ‘relate to’ was given its broad common-sense meaning.","cite":"481 U.S. 41, 47"}]},{"t":"case","label":"Presley v. Etowah Cty. Comm.","cite":"502 U.S. 491","y":1992,"id":"1991/90-711","sc":1,"by":{"1":"17, 19, 26","2":"13","3":"4"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Tr.","cite":"136 S. Ct. 1938","y":2016,"id":"2015/15-233","sc":1,"by":{"1":"16"},"q":[{"src":"brief","b":1,"text":"‘with the language of the statute itself.’","cite":"136 S. Ct. 1938, 1946"}]},{"t":"case","label":"Robinson v. J.R. Williston & Co.","cite":"266 F. 970","y":1920,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F./266/970/","by":{"1":"53"}},{"t":"case","label":"Rowe v. New Hampshire Motor Transp. Ass’n","cite":"552 U.S. 364","y":2008,"id":"2007/06-457","sc":1,"by":{"1":"21"}},{"t":"case","label":"Schwab v. Reilly","cite":"560 U.S. 770","y":2010,"id":"2009/08-538","sc":1,"by":{"1":"51"}},{"t":"case","label":"Scott v. Smith","cite":"232 F.2d 188","y":1956,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/232/188/","by":{"1":"43","2":"24"},"q":[{"src":"brief","b":1,"text":"had some ownership or control of property * * * available for hypothecation by him[] amounts to a statement ‘respecting his financial condition.’","cite":"232 F.2d 188, 190"}]},{"t":"case","label":"Sears, Roebuck & Co. v. Sofio","cite":"138 So. 2d 616","y":1962,"court":"La. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/138/616/","by":{"1":"47"}},{"t":"case","label":"Shainman v. Shear’s of Affton, Inc.","cite":"387 F.2d 33","y":1967,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/387/33/","by":{"1":"44","2":"24"},"q":[{"src":"brief","b":1,"text":"[a] written statement purporting to set forth the true value of a major asset of a corporation, its inventory, is a statement respecting the financial condition of that corporation.","cite":"387 F.2d 33, 38"}]},{"t":"case","label":"Sims v. Natural Prods. of Ga., LLC","cite":"785 S.E.2d 659","y":2016,"court":"Ga. Ct. App.","url":"https://www.courtlistener.com/c/S.E.2d/785/659/","by":{"1":"56"},"q":[{"src":"brief","b":1,"text":"normally, fraud cannot be predicated on statements which are in the nature of promises as to future events.","cite":"785 S.E.2d 659, 662"}]},{"t":"case","label":"Stellwagen v. Clum","cite":"245 U.S. 605","y":1918,"id":"scdb/1917-183","sc":1,"by":{"1":"4","2":"2"}},{"t":"case","label":"Texas Dep’t of Hous. & Cmty. Affairs v. Inclusive Cmtys. Project, Inc.","cite":"135 S. Ct. 2507","y":2015,"id":"2014/13-1371","sc":1,"by":{"1":"46"}},{"t":"case","label":"Till v. SCS Credit Corp.","cite":"541 U.S. 465","y":2004,"id":"2003/02-1016","sc":1,"by":{"1":"51"},"q":[{"src":"brief","b":1,"text":"minimiz[ing] the need for potentially costly additional evidentiary proceedings.","cite":"541 U.S. 465, 479"}]},{"t":"case","label":"United States v. Law","cite":"2011 WL 2945815","y":2011,"court":"D. Idaho","by":{"1":"28"}},{"t":"case","label":"United States v. Thomas","cite":"165 F. Supp. 3d 992","y":2015,"court":"D. Colo.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/165/992/","by":{"1":"28"}},{"t":"usc","label":"8 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/8/1330","subs":["(b)(3)(iii)(D)"],"by":{"1":"24"}},{"t":"usc","label":"12 U.S.C. § 4707","url":"https://www.law.cornell.edu/uscode/text/12/4707","subs":["(f)(1)(B)"],"by":{"1":"25"}},{"t":"usc","label":"15 U.S.C. § 1681a","url":"https://www.law.cornell.edu/uscode/text/15/1681a","by":{"1":"53"}},{"t":"usc","label":"28 U.S.C. § 3015","url":"https://www.law.cornell.edu/uscode/text/28/3015","subs":["(a)"],"by":{"1":"28"},"q":[{"src":"brief","b":1,"text":"discovery regarding the financial condition of the debtor.","cite":"28 U.S.C. § 3015(a)"}]},{"t":"usc","label":"29 U.S.C. § 1102","url":"https://www.law.cornell.edu/uscode/text/29/1102","subs":["(a)(1)"],"by":{"1":"52"},"q":[{"src":"brief","b":1,"text":"established and maintained pursuant to a written instrument","cite":"29 U.S.C. § 1102(a)(1)"}]},{"t":"usc","label":"31 U.S.C. § 5134","url":"https://www.law.cornell.edu/uscode/text/31/5134","subs":["(d)(2)"],"by":{"1":"25"}},{"t":"usc","label":"52 U.S.C. § 10304","url":"https://www.law.cornell.edu/uscode/text/52/10304","subs":["(a)"],"stext":{"head":"§10304. Alteration of voting qualifications; procedure and appeal; purpose or effect of diminishing the ability of citizens to elect their preferred candidates","paras":[[0,"(a) Whenever a State or political subdivision with respect to which the prohibitions set forth in section 10303(a) of this title based upon determinations made under the first sentence of section 10303(b) of this title are in effect shall enact or seek to administer any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting different from that in force or effect on November 1, 1964, or whenever a State or political subdivision with respect to which the prohibitions set forth in section 10303(a) of this title based upon determinations made under the second sentence of section 10303(b) of this title are in effect shall enact or seek to administer any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting different from that in force or effect on November 1, 1968, or whenever a State or political subdivision with respect to which the prohibitions set forth in section 10303(a) of this title based upon determinations made under the third sentence of section 10303(b) of this title are in effect shall enact or seek to administer any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting different from that in force or effect on November 1, 1972, such State or subdivision may institute an action in the United States District Court for the District of Columbia for a declaratory judgment that such qualification, prerequisite, standard, practice, or procedure neither has the purpose nor will have the effect of denying or abridging the right to vote on account of race or color, or in contravention of the guarantees set forth in section 10303(f)(2) of this title, and unless and until the court enters such judgment no person shall be denied the right to vote for failure to comply with such qualification, prerequisite, standard, practice, or procedure: Provided, That such qualification, prerequisite, standard, practice, or procedure may be enforced without such proceeding if the qualification, prerequisite, standard, practice, or procedure has been submitted by the chief legal officer or other appropriate official of such State or subdivision to the Attorney General and the Attorney General has not interposed an objection within sixty days after such submission, or upon good cause shown, to facilitate an expedited approval within sixty days after such submission, the Attorney General has affirmatively indicated that such objection will not be made. Neither an affirmative indication by the Attorney General that no objection will be made, nor the Attorney General's failure to object, nor a declaratory judgment entered under this section shall bar a subsequent action to enjoin enforcement of such qualification, prerequisite, standard, practice, or procedure. In the event the Attorney General affirmatively indicates that no objection will be made within the sixty-day period following receipt of a submission, the Attorney General may reserve the right to reexamine the submission if additional information comes to his attention during the remainder of the sixty-day period which would otherwise require objection in accordance with this section. Any action under this section shall be heard and determined by a court of three judges in accordance with the provisions of section 2284 of title 28 and any appeal shall lie to the Supreme Court."],[0,"(b) Any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting that has the purpose of or will have the effect of diminishing the ability of any citizens of the United States on account of race or color, or in contravention of the guarantees set forth in section 10303(f)(2) of this title, to elect their preferred candidates of choice denies or abridges the right to vote within the meaning of subsection (a) of this section."],[0,"(c) The term \"purpose\" in subsections (a) and (b) of this section shall include any discriminatory purpose."],[0,"(d) The purpose of subsection (b) of this section is to protect the ability of such citizens to elect their preferred candidates of choice."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/10304?type=usc&year=mostrecent&link-type=html"},"by":{"1":"19","3":"4"},"q":[{"src":"brief","b":1,"text":"standard, practice, or procedure with respect to voting.","cite":"52 U.S.C. § 10304"}]},{"t":"law","label":"Pub. L. No. 86-622","url":"https://www.govinfo.gov/link/statute/74/408","by":{"1":"43"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"18"}},{"t":"const","label":"Article I, Section 8, Clause 4","clauses":[["naturalization-bankruptcy","Naturalization and Bankruptcy Clause"]],"text":"To establish an uniform Rule of Naturalization, and uniform Laws on the subject of Bankruptcies throughout the United States;","by":{"1":"54"}},{"t":"const","label":"Article IV, Section 3, Clause 2","clauses":[["property-clause","Territory and Property Clause"]],"text":"The Congress shall have Power to dispose of and make all needful Rules and Regulations respecting the Territory or other Property belonging to the United States; and nothing in this Constitution shall be so construed as to Prejudice any Claims of the United States, or of any particular State.","by":{"1":"19","2":"13"}},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"by":{"2":"26"},"q":[{"src":"brief","b":2,"text":"inten[ded] to incorporate its * * * judicial interpretations as well.","cite":"524 U.S. 624, 645"}]},{"t":"case","label":"Central Va. Cmty. Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"by":{"2":"2"}},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich L.P.A.","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"by":{"2":"26"}},{"t":"case","label":"Park ’N Fly, Inc. v. Dollar Park & Fly, Inc.","cite":"469 U.S. 189","y":1985,"id":"1984/83-1132","sc":1,"by":{"2":"10"},"q":[{"src":"brief","b":2,"text":"Statutory construction must begin with the language employed by Congress and the assumption that the ordinary meaning of that language accurately expresses the legislative purpose.","cite":"469 U.S. 189, 194"}]},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"by":{"2":"12"}},{"t":"case","label":"Tyler v. Cain","cite":"533 U.S. 656","y":2001,"id":"2000/00-5961","sc":1,"by":{"2":"18"}},{"t":"case","label":"United States v. Ron Pair Enters., Inc.","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"by":{"2":"10"}},{"t":"case","label":"United States v. Spicer","cite":"57 F.3d 1152","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/57/1152/","by":{"2":"19"}},{"t":"law","label":"Pub. L. No. 86-821","url":"https://www.govinfo.gov/link/statute/74/408","by":{"2":"23"}},{"t":"usc","label":"11 U.S.C. § 111","url":"https://www.law.cornell.edu/uscode/text/11/111","subs":["(c)(2)(E)"],"by":{"2":"12"}},{"t":"usc","label":"11 U.S.C. § 363","url":"https://www.law.cornell.edu/uscode/text/11/363","subs":["(l)"],"by":{"2":"12"}},{"t":"usc","label":"11 U.S.C. § 365","url":"https://www.law.cornell.edu/uscode/text/11/365","subs":["(b)(2)(A)","(b)(3)(A)","(e)(1)(A)"],"by":{"2":"12, 12, 12"}},{"t":"usc","label":"11 U.S.C. § 524","url":"https://www.law.cornell.edu/uscode/text/11/524","subs":["(a)(1)","(a)(2)","(a)(3)","(g)(4)(A)(ii)(IV)"],"by":{"2":"10, 10, 10, 12"},"q":[{"src":"brief","b":2,"text":"operates as an injunction against the commencement or continuation of an action * * * to collect, recover or offset any such debt as a personal liability of the debtor.","cite":"11 U.S.C. 524(a)(2)"}]},{"t":"usc","label":"11 U.S.C. § 541","url":"https://www.law.cornell.edu/uscode/text/11/541","subs":["(c)(1)(B)"],"by":{"2":"12"}},{"t":"usc","label":"11 U.S.C. § 545","url":"https://www.law.cornell.edu/uscode/text/11/545","subs":["(1)(E)"],"by":{"2":"12"}},{"t":"usc","label":"11 U.S.C. § 727","url":"https://www.law.cornell.edu/uscode/text/11/727","subs":["(a)(3)"],"by":{"2":"10, 12"}},{"t":"usc","label":"11 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/11/1103","subs":["(c)(2)"],"stext":{"head":"§1103. Powers and duties of committees","paras":[[0,"(a) At a scheduled meeting of a committee appointed under section 1102 of this title, at which a majority of the members of such committee are present, and with the court's approval, such committee may select and authorize the employment by such committee of one or more attorneys, accountants, or other agents, to represent or perform services for such committee."],[0,"(b) An attorney or accountant employed to represent a committee appointed under section 1102 of this title may not, while employed by such committee, represent any other entity having an adverse interest in connection with the case. Representation of one or more creditors of the same class as represented by the committee shall not per se constitute the representation of an adverse interest."],[0,"(c) A committee appointed under section 1102 of this title may—"],[1,"(1) consult with the trustee or debtor in possession concerning the administration of the case;"],[1,"(2) investigate the acts, conduct, assets, liabilities, and financial condition of the debtor, the operation of the debtor's business and the desirability of the continuance of such business, and any other matter relevant to the case or to the formulation of a plan;"],[1,"(3) participate in the formulation of a plan, advise those represented by such committee of such committee's determinations as to any plan formulated, and collect and file with the court acceptances or rejections of a plan;"],[1,"(4) request the appointment of a trustee or examiner under section 1104 of this title; and"],[1,"(5) perform such other services as are in the interest of those represented."],[0,"(d) As soon as practicable after the appointment of a committee under section 1102 of this title, the trustee shall meet with such committee to transact such business as may be necessary and proper."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1103?type=usc&year=mostrecent&link-type=html"},"by":{"2":"12","3":"6"}},{"t":"usc","label":"11 U.S.C. § 1106","url":"https://www.law.cornell.edu/uscode/text/11/1106","subs":["(a)(3)"],"stext":{"head":"§1106. Duties of trustee and examiner","paras":[[0,"(a) A trustee shall—"],[1,"(1) perform the duties of the trustee, as specified in paragraphs (2), (5), (7), (8), (9), (10), (11), and (12) of section 704(a);"],[1,"(2) if the debtor has not done so, file the list, schedule, and statement required under section 521(a)(1) of this title;"],[1,"(3) except to the extent that the court orders otherwise, investigate the acts, conduct, assets, liabilities, and financial condition of the debtor, the operation of the debtor's business and the desirability of the continuance of such business, and any other matter relevant to the case or to the formulation of a plan;"],[1,"(4) as soon as practicable—"],[2,"(A) file a statement of any investigation conducted under paragraph (3) of this subsection, including any fact ascertained pertaining to fraud, dishonesty, incompetence, misconduct, mismanagement, or irregularity in the management of the affairs of the debtor, or to a cause of action available to the estate; and"],[2,"(B) transmit a copy or a summary of any such statement to any creditors' committee or equity security holders' committee, to any indenture trustee, and to such other entity as the court designates;"],[1,"(5) as soon as practicable, file a plan under section 1121 of this title, file a report of why the trustee will not file a plan, or recommend conversion of the case to a case under chapter 7, 12, or 13 of this title or dismissal of the case;"],[1,"(6) for any year for which the debtor has not filed a tax return required by law, furnish, without personal liability, such information as may be required by the governmental unit with which such tax return was to be filed, in light of the condition of the debtor's books and records and the availability of such information;"],[1,"(7) after confirmation of a plan, file such reports as are necessary or as the court orders; and"],[1,"(8) if with respect to the debtor there is a claim for a domestic support obligation, provide the applicable notice specified in subsection (c)."],[0,"(b) An examiner appointed under section 1104(d) of this title shall perform the duties specified in paragraphs (3) and (4) of subsection (a) of this section, and, except to the extent that the court orders otherwise, any other duties of the trustee that the court orders the debtor in possession not to perform."],[0,"(c)(1) In a case described in subsection (a)(8) to which subsection (a)(8) applies, the trustee shall—"],[1,"(A)(i) provide written notice to the holder of the claim described in subsection (a)(8) of such claim and of the right of such holder to use the services of the State child support enforcement agency established under sections 464 and 466 of the Social Security Act for the State in which such holder resides, for assistance in collecting child support during and after the case under this title; and"],[1,"(ii) include in the notice required by clause (i) the address and telephone number of such State child support enforcement agency;"],[1,"(B)(i) provide written notice to such State child support enforcement agency of such claim; and"],[1,"(ii) include in the notice required by clause (i) the name, address, and telephone number of such holder; and"],[1,"(C) at such time as the debtor is granted a discharge under section 1141, provide written notice to such holder and to such State child support enforcement agency of—"],[2,"(i) the granting of the discharge;"],[2,"(ii) the last recent known address of the debtor;"],[2,"(iii) the last recent known name and address of the debtor's employer; and"],[2,"(iv) the name of each creditor that holds a claim that—"],[3,"(I) is not discharged under paragraph (2), (4), or (14A) of section 523(a); or"],[3,"(II) was reaffirmed by the debtor under section 524(c)."],[0,"(2)(A) The holder of a claim described in subsection (a)(8) or the State child enforcement support agency of the State in which such holder resides may request from a creditor described in paragraph (1)(C)(iv) the last known address of the debtor."],[0,"(B) Notwithstanding any other provision of law, a creditor that makes a disclosure of a last known address of a debtor in connection with a request made under subparagraph (A) shall not be liable by reason of making such disclosure."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1106?type=usc&year=mostrecent&link-type=html"},"by":{"2":"12","3":"6"}},{"t":"usc","label":"11 U.S.C. § 1141","url":"https://www.law.cornell.edu/uscode/text/11/1141","subs":["(d)(6)"],"by":{"2":"10, 2"},"q":[{"src":"brief","b":2,"text":"to a person as the result of an action filed under subchapter III of chapter 37 of title 31 or any similar State statute.","cite":"11 U.S.C. 1141(d)(6)"}]},{"t":"usc","label":"11 U.S.C. § 1228","url":"https://www.law.cornell.edu/uscode/text/11/1228","by":{"2":"10"}},{"t":"usc","label":"11 U.S.C. § 1328","url":"https://www.law.cornell.edu/uscode/text/11/1328","by":{"2":"10"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","by":{"2":"2"}},{"t":"usc","label":"42 U.S.C. § 1973c","url":"https://www.law.cornell.edu/uscode/text/42/1973c","subs":["(1988)"],"by":{"2":"13"},"q":[{"src":"brief","b":2,"text":"changes ‘with respect to voting’ within the meaning of § 5 of the Voting Rights Act of 1965.","cite":"42 U.S.C. 1973c"}]},{"t":"reg","label":"82 Fed. Reg. 54,472","url":"https://www.govinfo.gov/link/fr/82/54472","by":{"2":"32"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"by":{"3":"20"},"q":[{"src":"brief","b":3,"text":"and there is no other evidence to suggest that Congress was even aware of the . . . interpretive position.","cite":"513 U.S. 115, 121"}]},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"by":{"3":"9"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"by":{"3":"7"}},{"t":"case","label":"Environmental Defense v. Duke Energy Corp.","cite":"549 U.S. 561","y":2007,"id":"2006/05-848","sc":1,"by":{"3":"3"}},{"t":"case","label":"Hancock v. Train","cite":"426 U.S. 167","y":1976,"id":"1975/74-220","sc":1,"by":{"3":"4"}},{"t":"case","label":"Hartford Underwriters Insurance Co. v. Union Planters Bank, N.A.","cite":"530 U.S. 1","y":2000,"id":"1999/99-409","sc":1,"by":{"3":"7"}},{"t":"case","label":"Page(s) Kelly v. Robinson","cite":"479 U.S. 36","y":1986,"id":"1986/85-1033","sc":1,"by":{"3":"16"}},{"t":"case","label":"Levin v. United States","cite":"568 U.S. 503","y":2013,"id":"2012/11-1351","sc":1,"by":{"3":"6"}},{"t":"case","label":"Metropolitan Stevedore Co. v. Rambo","cite":"515 U.S. 291","y":1995,"id":"1994/94-820","sc":1,"by":{"3":"20"}},{"t":"case","label":"Morse v. Republican Party of Virginia","cite":"517 U.S. 186","y":1996,"id":"1995/94-203","sc":1,"by":{"3":"4, 5"}},{"t":"case","label":"Murphy v. Smith","cite":"138 S. Ct. 784","y":2018,"id":"2017/16-1067","sc":1,"by":{"3":"6"}},{"t":"case","label":"New York State Conference of Blue Cross & Blue Shield Plans v. Travelers Insurance Co.","cite":"514 U.S. 645","y":1995,"id":"1994/93-1408","sc":1,"by":{"3":"12"}},{"t":"usc","label":"42 U.S.C. § 1857f","url":"https://www.law.cornell.edu/uscode/text/42/1857f","subs":["(1976)"],"by":{"3":"4"}},{"t":"law","label":"Pub. L. No. 95-598","url":"https://www.govinfo.gov/link/statute/92/2549","by":{"3":"9"}}]};